IF OBJECT_ID('dbo.CourseCategories','U') IS NULL CREATE TABLE dbo.CourseCategories(Id BIGINT IDENTITY PRIMARY KEY,Code NVARCHAR(100) NOT NULL UNIQUE,Name NVARCHAR(250) NOT NULL,Description NVARCHAR(1000) NULL,SortOrder INT NOT NULL DEFAULT 0,Status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE');
GO
IF OBJECT_ID('dbo.Courses','U') IS NULL CREATE TABLE dbo.Courses(
 Id BIGINT IDENTITY PRIMARY KEY,Code NVARCHAR(100) NOT NULL UNIQUE,Title NVARCHAR(500) NOT NULL,Slug NVARCHAR(500) NOT NULL UNIQUE,ThumbnailUrl NVARCHAR(1000) NULL,ShortDescription NVARCHAR(1000) NULL,Description NVARCHAR(MAX) NULL,
 TeacherId BIGINT NOT NULL,CategoryId BIGINT NULL,Level VARCHAR(50) NOT NULL DEFAULT 'BEGINNER',PassingScore DECIMAL(5,2) NOT NULL DEFAULT 0,Status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',PublishedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,CreatedBy BIGINT NOT NULL,UpdatedBy BIGINT NULL,IsDeleted BIT NOT NULL DEFAULT 0,
 CONSTRAINT FK_Courses_Teacher FOREIGN KEY(TeacherId) REFERENCES dbo.Users(Id),CONSTRAINT FK_Courses_Category FOREIGN KEY(CategoryId) REFERENCES dbo.CourseCategories(Id),CONSTRAINT CK_Courses_Status CHECK(Status IN('DRAFT','PUBLISHED','ARCHIVED')),CONSTRAINT CK_Courses_Score CHECK(PassingScore BETWEEN 0 AND 100));
GO
IF OBJECT_ID('dbo.Chapters','U') IS NULL CREATE TABLE dbo.Chapters(Id BIGINT IDENTITY PRIMARY KEY,CourseId BIGINT NOT NULL,Title NVARCHAR(500) NOT NULL,Description NVARCHAR(1000) NULL,SortOrder INT NOT NULL,Status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,IsDeleted BIT NOT NULL DEFAULT 0,CONSTRAINT FK_Chapters_Course FOREIGN KEY(CourseId) REFERENCES dbo.Courses(Id));
GO
IF OBJECT_ID('dbo.Lessons','U') IS NULL CREATE TABLE dbo.Lessons(Id BIGINT IDENTITY PRIMARY KEY,CourseId BIGINT NOT NULL,ChapterId BIGINT NOT NULL,Title NVARCHAR(500) NOT NULL,Description NVARCHAR(1000) NULL,LessonType VARCHAR(50) NOT NULL,DurationSeconds INT NOT NULL DEFAULT 0,SortOrder INT NOT NULL,IsRequired BIT NOT NULL DEFAULT 1,PassingScore DECIMAL(5,2) NULL,Status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,IsDeleted BIT NOT NULL DEFAULT 0,CONSTRAINT FK_Lessons_Course FOREIGN KEY(CourseId) REFERENCES dbo.Courses(Id),CONSTRAINT FK_Lessons_Chapter FOREIGN KEY(ChapterId) REFERENCES dbo.Chapters(Id),CONSTRAINT CK_Lessons_Type CHECK(LessonType IN('VIDEO','INTERACTIVE_VIDEO','QUIZ','DOCUMENT')));
GO
IF OBJECT_ID('dbo.Videos','U') IS NULL CREATE TABLE dbo.Videos(Id BIGINT IDENTITY PRIMARY KEY,LessonId BIGINT NOT NULL UNIQUE,Title NVARCHAR(500) NOT NULL,VideoUrl NVARCHAR(1000) NULL,PosterUrl NVARCHAR(1000) NULL,DurationSeconds INT NOT NULL,AllowSeek BIT NOT NULL DEFAULT 0,AllowSpeed BIT NOT NULL DEFAULT 1,RequiredWatchPercent DECIMAL(5,2) NOT NULL DEFAULT 80,Status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,CONSTRAINT FK_Videos_Lesson FOREIGN KEY(LessonId) REFERENCES dbo.Lessons(Id));
GO
IF OBJECT_ID('dbo.Questions','U') IS NULL CREATE TABLE dbo.Questions(Id BIGINT IDENTITY PRIMARY KEY,QuestionType VARCHAR(50) NOT NULL,QuestionText NVARCHAR(MAX) NOT NULL,Description NVARCHAR(MAX) NULL,Explanation NVARCHAR(MAX) NULL,Difficulty VARCHAR(30) NOT NULL,DefaultScore DECIMAL(8,2) NOT NULL DEFAULT 10,ShortAnswerMode VARCHAR(30) NULL,CreatedBy BIGINT NOT NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,Status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',IsDeleted BIT NOT NULL DEFAULT 0,CONSTRAINT FK_Questions_User FOREIGN KEY(CreatedBy) REFERENCES dbo.Users(Id),CONSTRAINT CK_Questions_Type CHECK(QuestionType IN('SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE','SHORT_ANSWER')));
GO
IF OBJECT_ID('dbo.QuestionOptions','U') IS NULL CREATE TABLE dbo.QuestionOptions(Id BIGINT IDENTITY PRIMARY KEY,QuestionId BIGINT NOT NULL,OptionCode NVARCHAR(20) NOT NULL,OptionText NVARCHAR(2000) NOT NULL,IsCorrect BIT NOT NULL DEFAULT 0,SortOrder INT NOT NULL,CONSTRAINT FK_QuestionOptions_Question FOREIGN KEY(QuestionId) REFERENCES dbo.Questions(Id),CONSTRAINT UQ_QuestionOptions UNIQUE(QuestionId,OptionCode));
GO
IF OBJECT_ID('dbo.QuestionAnswerKeys','U') IS NULL CREATE TABLE dbo.QuestionAnswerKeys(Id BIGINT IDENTITY PRIMARY KEY,QuestionId BIGINT NOT NULL,AnswerText NVARCHAR(2000) NOT NULL,IsCaseSensitive BIT NOT NULL DEFAULT 0,SortOrder INT NOT NULL,CONSTRAINT FK_QuestionKeys_Question FOREIGN KEY(QuestionId) REFERENCES dbo.Questions(Id));
GO
IF OBJECT_ID('dbo.VideoInteractions','U') IS NULL CREATE TABLE dbo.VideoInteractions(Id BIGINT IDENTITY PRIMARY KEY,VideoId BIGINT NOT NULL,QuestionId BIGINT NOT NULL,TimeSeconds INT NOT NULL,EndTimeSeconds INT NULL,InteractionType VARCHAR(50) NOT NULL,Required BIT NOT NULL DEFAULT 1,PauseVideo BIT NOT NULL DEFAULT 1,AllowSkip BIT NOT NULL DEFAULT 0,Score DECIMAL(8,2) NOT NULL DEFAULT 10,AttemptLimit INT NOT NULL DEFAULT 1,SortOrder INT NOT NULL,Status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NULL,IsDeleted BIT NOT NULL DEFAULT 0,CONSTRAINT FK_Interactions_Video FOREIGN KEY(VideoId) REFERENCES dbo.Videos(Id),CONSTRAINT FK_Interactions_Question FOREIGN KEY(QuestionId) REFERENCES dbo.Questions(Id));
GO
